const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const marovoayPoint = ee.Geometry.Point(46.64, -16.11);
  const region = marovoayPoint.buffer(5000); // 5km buffer to cover town and surrounding area
  const date1 = ee.Date('2020-01-27');
  const date2 = ee.Date('2017-01-18');

  // 2. Data Acquisition & Processing Function
  const getWaterExtent = (date, roi) => {
    const s1Collection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(roi)
      .filterDate(date, date.advance(1, 'day'))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'));

    const imageCount = s1Collection.size().getInfo();
    if (imageCount === 0) {
      return { count: 0, image: null };
    }

    const image = s1Collection.first();
    // A threshold of -16 dB on VV is commonly used to identify water bodies.
    const waterMask = image.select('VV').lt(-16);

    const waterImage = waterMask.updateMask(waterMask); // Mask so only water pixels are considered

    const stats = waterImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: 30, // Using a coarser scale to ensure computation completes
      maxPixels: 1e9
    });

    const waterPixelCount = ee.Number(stats.get('VV')).getInfo();

    return {
      count: imageCount,
      pixels: waterPixelCount
    };
  };

  // 3. Calculation for each date
  const result2020 = getWaterExtent(date1, region);
  const result2017 = getWaterExtent(date2, region);

  // 4. Validation & Final Answer
  console.log(`Images found for Jan 27, 2020: ${result2020.count}`);
  console.log(`Images found for Jan 18, 2017: ${result2017.count}`);

  if (result2020.count === 0 || result2017.count === 0) {
    console.log("Evidence: No image found for one or both dates.");
    console.log("A"); // C1
    return;
  }

  const waterPixels2020 = result2020.pixels;
  const waterPixels2017 = result2017.pixels;

  console.log(`Water Pixels (2020-01-27): ${waterPixels2020}`);
  console.log(`Water Pixels (2017-01-18): ${waterPixels2017}`);

  if (waterPixels2020 === null || waterPixels2017 === null) {
      console.log("Evidence: Calculation failed, received null for pixel count.");
      console.log("C3");
      return;
  }

  if (waterPixels2020 === 0 && waterPixels2017 === 0) {
      console.log("Evidence: No water pixels detected in the region for either date after processing.");
      console.log("C2");
      return;
  }

  if (waterPixels2020 > waterPixels2017) {
    console.log("Evidence: Water pixel count in 2020 was greater than in 2017.");
    console.log("A");
  } else {
    console.log("Evidence: Water pixel count in 2020 was not greater than in 2017.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
